/**
 * Pure ledger reduction logic. No filesystem or process access lives here.
 *
 * Events are objects of the form:
 *   { id: string, account: string, cents: safe nonnegative integer,
 *     kind: "credit" | "debit" }
 */

const EVENT_KEYS = ["id", "account", "cents", "kind"];

export class LedgerError extends Error {
  constructor(message) {
    super(message);
    this.name = "LedgerError";
  }
}

function fail(message) {
  throw new LedgerError(message);
}

function isPlainEventObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

/**
 * Validate one parsed event and return a normalized copy containing only the
 * four allowed fields. Extra or missing fields are rejected.
 */
export function validateEvent(value, label = "event") {
  if (!isPlainEventObject(value)) {
    fail(`${label}: must be a JSON object`);
  }

  const keys = Object.keys(value);
  if (
    keys.length !== EVENT_KEYS.length ||
    !EVENT_KEYS.every((key) => Object.hasOwn(value, key))
  ) {
    fail(`${label}: must contain exactly id, account, cents and kind`);
  }

  const { id, account, cents, kind } = value;

  if (typeof id !== "string" || id.length === 0) {
    fail(`${label}: id must be a nonempty string`);
  }
  if (typeof account !== "string" || account.length === 0) {
    fail(`${label}: account must be a nonempty string`);
  }
  if (!Number.isSafeInteger(cents) || cents < 0) {
    fail(`${label}: cents must be a nonnegative safe integer`);
  }
  if (kind !== "credit" && kind !== "debit") {
    fail(`${label}: kind must be "credit" or "debit"`);
  }

  return { id, account, cents, kind };
}

function sameEvent(a, b) {
  return (
    a.id === b.id &&
    a.account === b.account &&
    a.cents === b.cents &&
    a.kind === b.kind
  );
}

/** Compare two strings by Unicode code point (not UTF-16 code unit). */
export function compareByCodePoint(a, b) {
  const left = Array.from(a);
  const right = Array.from(b);
  const length = Math.min(left.length, right.length);

  for (let index = 0; index < length; index += 1) {
    const aPoint = left[index].codePointAt(0);
    const bPoint = right[index].codePointAt(0);
    if (aPoint !== bPoint) {
      return aPoint < bPoint ? -1 : 1;
    }
  }

  return left.length - right.length;
}

function addSafe(a, b, label) {
  const result = a + b;
  if (!Number.isSafeInteger(result)) {
    fail(`${label}: total exceeds the safe integer range`);
  }
  return result;
}

/**
 * Reduce parsed events.
 *
 * Identical duplicates (same id and all fields) are counted once. Two records
 * with the same id but different content make the whole input invalid.
 *
 * options.account, when supplied, filters the reported accounts and netCents.
 * The event counts always describe the whole input.
 */
export function reduceEvents(events, options = {}) {
  if (
    events === null ||
    events === undefined ||
    typeof events[Symbol.iterator] !== "function"
  ) {
    fail("events must be an iterable of event objects");
  }

  const filterAccount = options.account;
  if (filterAccount !== undefined && typeof filterAccount !== "string") {
    fail("account filter must be a string");
  }

  const byId = new Map();
  let duplicateEvents = 0;

  for (const rawEvent of events) {
    const event = validateEvent(rawEvent);
    const previous = byId.get(event.id);

    if (previous === undefined) {
      byId.set(event.id, event);
    } else if (sameEvent(previous, event)) {
      duplicateEvents += 1;
    } else {
      fail(`conflicting records share id ${JSON.stringify(event.id)}`);
    }
  }

  const balances = new Map();
  for (const event of byId.values()) {
    const current = balances.get(event.account) ?? 0;
    const delta = event.kind === "credit" ? event.cents : -event.cents;
    balances.set(event.account, addSafe(current, delta, "account balance"));
  }

  const allAccounts = Array.from(balances, ([account, balanceCents]) => ({
    account,
    balanceCents,
  })).sort((a, b) => compareByCodePoint(a.account, b.account));

  let netCents = 0;
  for (const entry of allAccounts) {
    netCents = addSafe(netCents, entry.balanceCents, "net balance");
  }

  const accounts =
    filterAccount === undefined
      ? allAccounts
      : allAccounts.filter((entry) => entry.account === filterAccount);

  const filteredNetCents =
    filterAccount === undefined
      ? netCents
      : accounts.reduce(
          (sum, entry) => addSafe(sum, entry.balanceCents, "net balance"),
          0,
        );

  return {
    uniqueEvents: byId.size,
    duplicateEvents,
    accounts,
    netCents: filteredNetCents,
  };
}

/**
 * Parse UTF-8 JSONL text. Blank/whitespace-only lines are ignored. JSON or
 * shape errors are reported with a 1-based line number.
 */
export function parseJsonl(text) {
  if (typeof text !== "string") {
    fail("input must be text");
  }

  // A UTF-8 BOM is permitted at the beginning of the file.
  if (text.charCodeAt(0) === 0xfeff) {
    text = text.slice(1);
  }

  const lines = text.split(/\r\n|\n|\r/);
  const events = [];

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    if (line.trim() === "") {
      continue;
    }

    let parsed;
    try {
      parsed = JSON.parse(line);
    } catch {
      fail(`line ${index + 1}: malformed JSON`);
    }

    events.push(validateEvent(parsed, `line ${index + 1}`));
  }

  return events;
}

// Friendly aliases for callers that expect a differently named reducer.
export { reduceEvents as reduce };
export default reduceEvents;

#!/usr/bin/env node

import { randomUUID } from "node:crypto";
import { readFile, mkdir, writeFile, rename, unlink } from "node:fs/promises";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import {
  LedgerError,
  parseJsonl,
  reduceEvents,
} from "./ledger.mjs";

const USAGE = "usage: node reconcile.mjs INPUT OUTPUT [--account NAME]";

function fail(message) {
  throw new LedgerError(message);
}

/**
 * Parse CLI arguments. Positional INPUT/OUTPUT may appear on either side of
 * the optional --account flag.
 */
export function parseArgs(argv) {
  let input;
  let output;
  let account;

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];

    if (arg === "--account") {
      if (account !== undefined) {
        fail("--account may only be supplied once");
      }
      index += 1;
      if (index >= argv.length) {
        fail(`--account requires a name\n${USAGE}`);
      }
      account = argv[index];
    } else if (arg.startsWith("--account=")) {
      if (account !== undefined) {
        fail("--account may only be supplied once");
      }
      account = arg.slice("--account=".length);
    } else if (arg.startsWith("-") && arg !== "-") {
      fail(`unknown option ${JSON.stringify(arg)}\n${USAGE}`);
    } else if (input === undefined) {
      input = arg;
    } else if (output === undefined) {
      output = arg;
    } else {
      fail(`unexpected argument ${JSON.stringify(arg)}\n${USAGE}`);
    }
  }

  if (input === undefined || output === undefined) {
    fail(`INPUT and OUTPUT are required\n${USAGE}`);
  }

  return { input, output, account };
}

async function readUtf8File(path) {
  const buffer = await readFile(path);
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(buffer);
  } catch {
    fail(`${path}: input is not valid UTF-8`);
  }
}

/**
 * Write the rendered JSON next to OUTPUT and atomically rename it into place.
 * A failure before the rename leaves an existing OUTPUT untouched.
 */
async function writeAtomic(outputPath, contents) {
  const directory = dirname(outputPath);
  await mkdir(directory, { recursive: true });

  const temporaryPath = join(
    directory,
    `.${basename(outputPath)}.${process.pid}.${randomUUID()}.tmp`,
  );

  try {
    await writeFile(temporaryPath, contents, { encoding: "utf8", flag: "wx" });
    await rename(temporaryPath, outputPath);
  } catch (error) {
    try {
      await unlink(temporaryPath);
    } catch {
      // The temporary file may never have been created.
    }
    throw error;
  }
}

/**
 * Run the CLI. Returns normally on success; throws LedgerError (or a
 * filesystem error) on failure.
 */
export async function main(argv = process.argv.slice(2)) {
  const { input, output, account } = parseArgs(argv);

  // Read and fully validate everything before touching OUTPUT.
  const text = await readUtf8File(input);
  const events = parseJsonl(text);
  const result = reduceEvents(events, { account });

  const rendered = `${JSON.stringify(result, null, 2)}\n`;
  await writeAtomic(output, rendered);
}

function isDirectRun() {
  const invokedPath = process.argv[1];
  return (
    typeof invokedPath === "string" &&
    resolve(invokedPath) === fileURLToPath(import.meta.url)
  );
}

if (isDirectRun()) {
  main().catch((error) => {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`reconcile: ${message}\n`);
    process.exitCode = 1;
  });
}

import test from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

import {
  LedgerError,
  compareByCodePoint,
  parseJsonl,
  reduceEvents,
} from "./ledger.mjs";

const CLI = fileURLToPath(new URL("./reconcile.mjs", import.meta.url));

function runCli(args) {
  return spawnSync(process.execPath, [CLI, ...args], {
    encoding: "utf8",
  });
}

async function makeTempDir(t) {
  const directory = await mkdtemp(join(tmpdir(), "ledger-test-"));
  t.after(() => rm(directory, { recursive: true, force: true }));
  return directory;
}

function event(id, account, cents, kind) {
  return { id, account, cents, kind };
}

test("identical duplicate ids are counted once and reported", () => {
  const result = reduceEvents([
    event("a", "alpha", 100, "credit"),
    event("b", "beta", 40, "debit"),
    event("a", "alpha", 100, "credit"),
    event("a", "alpha", 100, "credit"),
  ]);

  assert.deepEqual(result, {
    uniqueEvents: 2,
    duplicateEvents: 2,
    accounts: [
      { account: "alpha", balanceCents: 100 },
      { account: "beta", balanceCents: -40 },
    ],
    netCents: 60,
  });
});

test("conflicting records with the same id invalidate the input", () => {
  assert.throws(
    () =>
      reduceEvents([
        event("same", "alpha", 100, "credit"),
        event("same", "alpha", 101, "credit"),
      ]),
    (error) =>
      error instanceof LedgerError &&
      /conflicting records share id "same"/.test(error.message),
  );

  assert.throws(
    () =>
      reduceEvents([
        event("same", "alpha", 100, "credit"),
        event("same", "alpha", 100, "debit"),
      ]),
    LedgerError,
  );
});

test("integer arithmetic stays exact at the safe integer boundary", () => {
  const result = reduceEvents([
    event("max", "big", Number.MAX_SAFE_INTEGER, "credit"),
    event("minus", "big", Number.MAX_SAFE_INTEGER - 1, "debit"),
    event("small", "small", 1, "credit"),
  ]);

  assert.deepEqual(result.accounts, [
    { account: "big", balanceCents: 1 },
    { account: "small", balanceCents: 1 },
  ]);
  assert.equal(result.netCents, 2);

  assert.throws(
    () =>
      reduceEvents([
        event("max", "big", Number.MAX_SAFE_INTEGER, "credit"),
        event("overflow", "big", 1, "credit"),
      ]),
    /safe integer range/,
  );
});

test("invalid fields are rejected", () => {
  const invalidEvents = [
    null,
    [],
    {},
    { id: "", account: "alpha", cents: 1, kind: "credit" },
    { id: 7, account: "alpha", cents: 1, kind: "credit" },
    { id: "a", account: "", cents: 1, kind: "credit" },
    { id: "a", account: "alpha", cents: -1, kind: "credit" },
    { id: "a", account: "alpha", cents: 1.5, kind: "credit" },
    { id: "a", account: "alpha", cents: Number.MAX_SAFE_INTEGER + 1, kind: "credit" },
    { id: "a", account: "alpha", cents: 1, kind: "Credit" },
    { id: "a", account: "alpha", cents: 1, kind: "credit", extra: true },
  ];

  for (const invalid of invalidEvents) {
    assert.throws(() => reduceEvents([invalid]), LedgerError);
  }
});

test("accounts sort by Unicode code point, including astral characters", () => {
  const names = ["a", "Z", "é", "\uFFFF", "😀"];
  const result = reduceEvents(
    names.map((account, index) => event(`id-${index}`, account, 1, "credit")),
  );

  assert.deepEqual(
    result.accounts.map((entry) => entry.account),
    ["Z", "a", "é", "\uFFFF", "😀"],
  );
  assert.equal(compareByCodePoint("😀", "\uFFFF"), 1);
});

test("parseJsonl ignores blank lines and reports malformed line numbers", () => {
  const events = parseJsonl(
    '\n{"id":"a","account":"alpha","cents":1,"kind":"credit"}\r\n   \n',
  );
  assert.equal(events.length, 1);

  assert.throws(() => parseJsonl("\n\nnot json\n"), /line 3: malformed JSON/);
});

test("CLI writes the exact shape, creates parent directories and deduplicates", async (t) => {
  const directory = await makeTempDir(t);
  const input = join(directory, "input.jsonl");
  const output = join(directory, "nested", "deep", "report.json");

  await writeFile(
    input,
    [
      '{"id":"a","account":"alpha","cents":500,"kind":"credit"}',
      "",
      '{"id":"b","account":"beta","cents":125,"kind":"debit"}',
      '{"id":"a","account":"alpha","cents":500,"kind":"credit"}',
      "   ",
      '{"id":"c","account":"alpha","cents":25,"kind":"credit"}',
      "",
    ].join("\n"),
    "utf8",
  );

  const run = runCli([input, output]);
  assert.equal(run.status, 0, run.stderr);

  const parsed = JSON.parse(await readFile(output, "utf8"));
  assert.deepEqual(Object.keys(parsed), [
    "uniqueEvents",
    "duplicateEvents",
    "accounts",
    "netCents",
  ]);
  assert.deepEqual(parsed, {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [
      { account: "alpha", balanceCents: 525 },
      { account: "beta", balanceCents: -125 },
    ],
    netCents: 400,
  });
});

test("--account filters balances but not whole-input event counts", async (t) => {
  const directory = await makeTempDir(t);
  const input = join(directory, "input.jsonl");
  const output = join(directory, "filtered.json");

  await writeFile(
    input,
    [
      '{"id":"a","account":"alpha","cents":50,"kind":"credit"}',
      '{"id":"b","account":"beta","cents":20,"kind":"debit"}',
      '{"id":"a","account":"alpha","cents":50,"kind":"credit"}',
      '{"id":"c","account":"alpha","cents":25,"kind":"credit"}',
    ].join("\n"),
    "utf8",
  );

  let run = runCli([input, output, "--account", "alpha"]);
  assert.equal(run.status, 0, run.stderr);
  assert.deepEqual(JSON.parse(await readFile(output, "utf8")), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [{ account: "alpha", balanceCents: 75 }],
    netCents: 75,
  });

  run = runCli(["--account=missing", input, output]);
  assert.equal(run.status, 0, run.stderr);
  assert.deepEqual(JSON.parse(await readFile(output, "utf8")), {
    uniqueEvents: 3,
    duplicateEvents: 1,
    accounts: [],
    netCents: 0,
  });
});

test("invalid input fails nonzero and preserves an existing output", async (t) => {
  const directory = await makeTempDir(t);
  const input = join(directory, "input.jsonl");
  const output = join(directory, "existing.json");
  const sentinel = '{"keep":"this exact content"}\n';

  await writeFile(output, sentinel, "utf8");

  const badInputs = [
    '{"id":"a","account":"alpha","cents":1,"kind":"credit"}\nnot json\n',
    '{"id":"a","account":"alpha","cents":-1,"kind":"credit"}\n',
    '{"id":"a","account":"alpha","cents":1,"kind":"credit"}\n' +
      '{"id":"a","account":"alpha","cents":2,"kind":"credit"}\n',
    '{"id":"a","account":"alpha","cents":1,"kind":"credit","extra":1}\n',
  ];

  for (const contents of badInputs) {
    await writeFile(input, contents, "utf8");
    const run = runCli([input, output]);
    assert.equal(run.status, 1, `expected failure for: ${contents}`);
    assert.notEqual(run.stderr.length, 0);
    assert.equal(await readFile(output, "utf8"), sentinel);
  }

  // A missing input is also an error before the output is replaced.
  const run = runCli([join(directory, "does-not-exist.jsonl"), output]);
  assert.equal(run.status, 1);
  assert.equal(await readFile(output, "utf8"), sentinel);
});

test("invalid UTF-8 fails without replacing an existing output", async (t) => {
  const directory = await makeTempDir(t);
  const input = join(directory, "invalid.jsonl");
  const output = join(directory, "existing.json");

  await writeFile(input, Buffer.from([0x7b, 0xff, 0x7d]));
  await writeFile(output, "preserve me", "utf8");

  const run = runCli([input, output]);
  assert.equal(run.status, 1);
  assert.match(run.stderr, /not valid UTF-8/);
  assert.equal(await readFile(output, "utf8"), "preserve me");
});

